package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen1Test {



















    @Test
    public void testParseOctal_TrailingSpaces() {
        // The code has a logic: trailer = buffer[end-1]. 
        // While (start < end && (trailer == 0 || false))
        // Since 'false' is always false, the loop 'while (start < end && (trailer == 0 || false))'
        // effectively only runs if trailer == 0.
        // This means trailing spaces are NOT trimmed by the NUL loop, 
        // but the main loop will hit ' ' and throw IllegalArgumentException 
        // because ' ' is not between '0' and '7'.

        // However, let's test the behavior as written.
        byte[] buffer = "000123 ".getBytes(); 
        try {
            TarUtils.parseOctal(buffer, 0, 7);
            fail("Should have thrown exception because space is not octal");
        } catch (IllegalArgumentException e) {
            // Expected
        }
    }




}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen1Test {





















    @Test
    public void testParseOctal_TrailingNUL() {
        // The loop 'while (start < end && (trailer == 0 || false))'
        // If the last byte is 0, end decrements.
        byte[] buffer = {'0', '0', '1', '0', 0}; 
        // offset 0, length 5. end = 5. buffer[4] is 0.
        // end becomes 4. trailer becomes buffer[3] ('0'). Loop stops.
        // result = 0010 (octal) = 8.
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(8L, result);
    }


}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen1Test {























    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_AllNULs() {
        // If all are NULs, the loop might reduce end until start == end
        byte[] buffer = {0, 0, 0};
        // buffer[0] is 0, returns 0L immediately based on the first if(buffer[start] == 0)
        // To trigger the start == end exception, we need buffer[start] != 0 but trailing NULs
        byte[] buffer2 = {'1', 0, 0};
        // start=0, end=3. buffer[2]=0. end=2. trailer=buffer[1]=0. end=1. trailer=buffer[0]='1'.
        // Loop stops. result = 1.
        // To trigger start == end, we need to bypass the buffer[start]==0 check.
        byte[] buffer3 = {' ', 0, 0}; 
        // buffer[0] is ' ', so it skips to start=1. 
        // end=3. trailer=0. end=2. trailer=0. end=1. trailer=' '.
        // start=1, end=1. start == end. Throws exception.
        TarUtils.parseOctal(buffer3, 0, 3);
    }
}
